# Generated by AMP. Starts RabbitMQ and passes each console line to rabbitmqctl (for example: status, list_queues, stop).
Set-Location -LiteralPath $PSScriptRoot
$env:HOMEDRIVE = Split-Path -Path $PSScriptRoot -Qualifier
$env:HOMEPATH = Split-Path -Path $PSScriptRoot -NoQualifier
if (-not (Test-Path -Path 'nodename.txt')) { Set-Content -Path 'nodename.txt' -Value ('rabbit-' + [guid]::NewGuid().ToString('N').Substring(0, 8) + '@localhost') }
$env:RABBITMQ_NODENAME = (Get-Content -Path 'nodename.txt' -Raw).Trim()
$Server = Start-Process -FilePath $env:ComSpec -ArgumentList '/D /C call server\sbin\rabbitmq-server.bat < NUL' -NoNewWindow -PassThru
$null = $Server.Handle
$Stdin = New-Object System.IO.StreamReader([Console]::OpenStandardInput())
$Read = $Stdin.ReadLineAsync()
while (-not $Server.HasExited) {
    if ($null -eq $Read) { Start-Sleep -Milliseconds 500; continue }
    if (-not $Read.Wait(500)) { continue }
    $Line = $Read.Result
    if ($null -eq $Line) { $Read = $null; continue }
    $Arguments = @($Line.Trim() -split '\s+' | Where-Object { $_ })
    if ($Arguments.Count -gt 0) { $null | & '.\server\sbin\rabbitmqctl.bat' @Arguments }
    $Read = $Stdin.ReadLineAsync()
}
$Server.WaitForExit()
exit $Server.ExitCode
